// и имени молитвы (שחרית/מנחה/ערבית); случай тикета — «צהריים טובים» + «מנחה» (с QA_GREETING_STRICT=1 вне этого окна — skip).
// Дата в шапке при длинном имени (#58ba6a, 47b60dea, עבר QA 03.11) — отдельный тест q-26 (HM-10).
// Данные: меняет «שם מלא» вошедшего аккаунта (03.11 — 0537240114 «QA reg 0311», вход реальным SMS) и в finally возвращает
// исходное имя, прочитанное из поля (запасное — QA_GREETING_RESTORE_NAME, по умолчанию «QA reg 0311»). Имена — ровно те, что
// мерили 03.11 (длина важна для числа строк), а не QA-AUTO-… : это временная правка профиля, не создаваемая запись.
// Платформа: только iPhone (тикет iOS; на Android не проверялось → skip). Кейс: .qa/tests/home/HM-09-greeting-no-overlap-long-name.md.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { $, driver, expect } from '@wdio/globals';
import { byTextContains, byLabel } from '../../helpers/ui.ts';
import { toHome } from '../../helpers/app.ts';
import { rectOf, staticText, type Rect } from '../_lib/app-1310.ts';
import { shown, skipWith } from '../_lib/app-0710.ts';
import { NAME_LONG, readProfileName, backToHome, setProfileName as setName, stableRect } from '../_lib/app-0311.ts';

const QA_DIR = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../../..');
const SHOTS = path.join(QA_DIR, 'screenshots/app-regress/qa-0311');

const GREETING_TAIL = ', מוכן לתפילה';            // «<ברכה> <שם>, מוכן לתפילה מרוממת?»
const GREETINGS = ['בוקר טוב', 'צהריים טובים', 'ערב טוב'];
const PRAYER_NAMES = ['שחרית', 'מנחה', 'ערבית'];
const MIN_GAP = 8;                                   // pt; 03.11 минимум был 16
const NAME_MEDIUM = 'Tatiana Dombek';                // 03.11: 3 строки
// NAME_LONG «Tatiana Dombek Alexandrovna Longname» (03.11: 4 строки) — из _lib/app-0311.ts

type Measure = { name: string; greeting: string; g: Rect; prayer: string; p: Rect; gap: number; lines: number };

async function saveShot(file: string) {
  fs.mkdirSync(SHOTS, { recursive: true });
  await driver.saveScreenshot(path.join(SHOTS, file));
}

/** Именно текстовый элемент приветствия (не склеенная подпись контейнера). */
function greetingEl(name: string) {
  const part = `${name}${GREETING_TAIL}`.replace(/"/g, '\\"');
  return driver.isAndroid
    ? $(`android=new UiSelector().textContains("${part}")`)
    : $(`-ios predicate string:type == "XCUIElementTypeStaticText" AND label CONTAINS "${part}"`);
}

/** Замер шапки главной для текущего имени. */
async function measure(name: string, shot: string): Promise<Measure> {
  await (await byLabel('התחל תפילה')).waitForDisplayed({ timeout: 20000 });
  const g = await stableRect(() => greetingEl(name), `приветствие с «${name}»`);
  const greeting = String(await (await greetingEl(name)).getAttribute(driver.isAndroid ? 'text' : 'label'));
  expect(GREETINGS.some((w) => greeting.startsWith(`${w} `))).toBe(true);

  let prayer = '';
  for (const n of PRAYER_NAMES) if (await shown(staticText(n))) { prayer = n; break; }
  expect(prayer).not.toBe('');
  const p = await rectOf(staticText(prayer));
  const gap = p.y - (g.y + g.height);
  const lines = Math.round(g.height / 24);
  await saveShot(shot);
  console.log(`[Q-25] «${name}»: «${greeting}» y${g.y} h${g.height} (~${lines} стр.); «${prayer}» y${p.y}; зазор ${gap}`);

  // Главное требование тикета: приветствие не заходит на имя молитвы, есть зазор.
  expect(p.y).toBeGreaterThanOrEqual(g.y + g.height + MIN_GAP);
  expect(p.height).toBeGreaterThan(0);
  return { name, greeting, g, prayer, p, gap, lines };
}

describe('03.11 — главная: приветствие не налезает на имя молитвы (#85332a)', () => {
  afterEach(async () => { await toHome().catch(() => {}); });

  it('HM-09 Приветствие «<ברכה> <שם>, מוכן לתפילה מרוממת?» при имени 2/3/4 строки не налезает на «מנחה» (зазор ≥ 8 pt), длиннее — «מנחה» ниже; имя возвращается #85332a #0a168fbe @iphone @data', async function () {
    if (driver.isAndroid) skipWith(this, '#85332a — тикет iOS, проверен на iPhone 17; Android не проверялся');

    // Окно «צהריים» — случай тикета. Без QA_GREETING_STRICT тот же критерий проверяется для любой текущей ברכה.
    await toHome();
    await (await byLabel('התחל תפילה')).waitForDisplayed({ timeout: 20000 });
    const noon = await shown(byTextContains(`צהריים טובים `));
    if (!noon && process.env.QA_GREETING_STRICT === '1') skipWith(this, 'сейчас не окно «צהריים טובים» (QA_GREETING_STRICT=1)');
    if (!noon) console.warn('[Q-25] сейчас не «צהריים טובים» — проверяю тот же критерий для текущей ברכה');

    // Исходное имя — из поля «שם מלא».
    const original = await readProfileName();

    const results: Measure[] = [];
    try {
      results.push(await measure(original, '85332a-q25-1-original.png'));
      await setName(NAME_MEDIUM);
      results.push(await measure(NAME_MEDIUM, '85332a-q25-2-medium.png'));
      await setName(NAME_LONG);
      const long = await measure(NAME_LONG, '85332a-q25-3-long.png');
      results.push(long);

      // Шапка растёт по содержимому: приветствие с самым длинным именем не ниже по высоте, чем с исходным,
      // а если выросло — имя молитвы сдвинулось вниз (а не осталось на месте под наложением).
      const first = results[0];
      expect(long.g.height).toBeGreaterThanOrEqual(first.g.height);
      if (long.g.height > first.g.height) expect(long.p.y).toBeGreaterThan(first.p.y);
    } finally {
      // Уборка: вернуть исходное имя (03.11 — «QA reg 0311») и убедиться, что оно на главной.
      await backToHome().catch(() => {});
      await setName(original);
      await (await greetingEl(original)).waitForDisplayed({ timeout: 20000 });
    }
  });
});
